function buscarParte(parte, tipo) {
  if (!parte) return null;
  if (parte.mimeType === tipo && parte.body?.data) return parte.body.data;
  for (const p of (parte.parts || [])) {
    const r = buscarParte(p, tipo);
    if (r) return r;
  }
  return null;
}

function aTexto(html) {
  return html
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
    .replace(/&aacute;/g, 'á').replace(/&eacute;/g, 'é').replace(/&iacute;/g, 'í')
    .replace(/&oacute;/g, 'ó').replace(/&uacute;/g, 'ú').replace(/&ntilde;/g, 'ñ')
    .replace(/\s+/g, ' ').trim();
}

const c = $json;

let cuerpo = '';
if (typeof c.html === 'string' && c.html) {
  cuerpo = aTexto(c.html);
} else if (typeof c.text === 'string' && c.text) {
  cuerpo = c.text.replace(/\s+/g, ' ').trim();
} else {
  const payload = c.payload || {};
  const data = buscarParte(payload, 'text/html') || buscarParte(payload, 'text/plain') || payload.body?.data || null;
  const html = data ? Buffer.from(data.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf-8') : '';
  cuerpo = aTexto(html);
}

const cab = c.payload?.headers || [];
const asunto = c.subject || c.Subject || (cab.find(h => (h.name || '').toLowerCase() === 'subject') || {}).value || '';

let ms = Number(c.internalDate);
if (!Number.isFinite(ms)) ms = c.date ? new Date(c.date).getTime() : NaN;
if (!Number.isFinite(ms)) ms = Date.now();
const fecha = new Date(ms - 5 * 60 * 60 * 1000).toISOString().slice(0, 10);   // hora de Colombia (UTC-5)

return { json: { messageId: c.id || c.messageId || '', fecha, ms, texto: ('Asunto: ' + asunto + '. ' + cuerpo).slice(0, 4000) } };

const crudo = $json.content?.[0]?.text || $json.text || '';
const base = $('Limpiar').item.json;

let p = null;
try { p = JSON.parse(crudo.replace(/```json|```/g, '').trim()); } catch (e) { p = null; }

const CATEGORIAS = ['Hogar', 'Hijo', 'Carro', 'Alimentación', 'Servicios', 'Salud', 'Salidas', 'Ahorro', 'Otros', 'Tarjetas'];
const fmt = n => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const cus = (base.texto.match(/CUS:?\s*(\d{5,})/i) || [])[1] || null;

let valido = false, monto = null, fecha = base.fecha;
let concepto = String(p?.concepto || '').trim().slice(0, 60);
let categoria = CATEGORIAS.includes(p?.categoria) ? p.categoria : 'Otros';

if (p && concepto && Number.isFinite(Number(p.monto)) && Number(p.monto) > 0 && cus) {
  monto = Math.round(Number(p.monto));
  valido = base.texto.includes(fmt(monto));          // el monto tiene que estar escrito en el correo
  const m = String(p.fecha || '').match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (m && base.texto.includes(p.fecha)) fecha = m[3] + '-' + m[2] + '-' + m[1];
}

// Claro (COMCEL): Alejandra paga los dos celulares, así que no se distingue por el nombre del correo sino por el día de pago.
// Pagado del 1 al 5 → «Celular Aleja»; cualquier otro día (el suyo es del 15 al 23) → «Celular amor» (el de Carlos).
if (/COMCEL/i.test(base.texto) || /^celular$/i.test(concepto)) {
  concepto = Number(String(fecha).slice(8, 10)) <= 5 ? 'Celular Aleja' : 'Celular amor';
  categoria = 'Hogar';
}
return { json: { valido, concepto, categoria, monto, fecha, cus, notas: cus ? 'PSE · CUS ' + cus : '', messageId: base.messageId, ms: base.ms } };

// Pagos que pasaron la validación
const nuevos = $('If').all().map(i => i.json);
// Todo lo que ya está en Movimientos
const filas = $input.all().map(i => i.json).filter(f => f && f.property_monto !== undefined);
const dias = s => Math.floor(new Date(String(s).slice(0, 10) + 'T00:00:00Z').getTime() / 86400000);

const usadas = new Set();   // cada pago anotado a mano solo "cancela" a un pago del correo
const vistos = new Set();   // el mismo pago repetido dentro de esta tanda (por CUS)
const salida = [];

for (const c of nuevos) {
  const clave = c.cus || c.messageId;
  if (vistos.has(clave)) continue;
  vistos.add(clave);

  // 1) este mismo pago (mismo CUS) ya lo registró el flujo
  if (c.cus && filas.some(f => String(f.property_notas || '').includes(c.cus))) continue;

  // 2) ya lo anotaron a mano: mismo valor en los mismos días (cada fila a mano se usa una sola vez)
  const idx = filas.findIndex((f, i) =>
    !usadas.has(i) &&
    !String(f.property_notas || '').includes('PSE · CUS') &&
    Number(f.property_monto) === c.monto &&
    f.property_fecha?.start &&
    Math.abs(dias(f.property_fecha.start) - dias(c.fecha)) <= 5
  );
  if (idx >= 0) { usadas.add(idx); continue; }

  salida.push({ json: c });
}

// se crean de más antiguo a más nuevo (así "Creado" queda en el mismo orden que los pagos)
salida.sort((a, b) => String(a.json.fecha).localeCompare(String(b.json.fecha)) || (a.json.ms || 0) - (b.json.ms || 0));
return salida;

// La cuota del carro que llega por PSE (o se anota en Movimientos) también va a la tabla «Pago del Carro»,
// calculando capital, interés, seguros y saldo a partir de la última cuota registrada.
const txt = (a) => ((a || []).map(t => t.plain_text).join('') || '').trim();
const clave = (n) => 'property_' + String(n).toLowerCase().replace(/\s+/g, '_');
const leer = (it, nombre, tipo) => {
  const pr = it.properties && it.properties[nombre];
  if (pr) {
    if (tipo === 'titulo') return txt(pr.title);
    if (tipo === 'texto') return txt(pr.rich_text);
    if (tipo === 'numero') return pr.number != null ? pr.number : null;
    if (tipo === 'fecha') return pr.date && pr.date.start ? pr.date.start.slice(0, 10) : null;
    if (tipo === 'select') return pr.select ? pr.select.name : null;
  }
  let v = it[clave(nombre)];
  if (v === undefined && tipo === 'titulo') v = it.name;
  if (v === undefined || v === null || v === '') return null;
  if (tipo === 'fecha') { const s = typeof v === 'object' ? (v.start || '') : String(v); return s ? s.slice(0, 10) : null; }
  if (tipo === 'numero') return typeof v === 'number' ? v : (Number(v) || null);
  return String(v);
};
const norm = t => String(t || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();
const dias = s => Math.floor(new Date(String(s).slice(0, 10) + 'T00:00:00Z').getTime() / 864e5);
const r2 = n => Math.round(n * 100) / 100;

// lo que ya está en «Pago del Carro»
const pagos = $input.all().map(i => i.json).filter(x => x && x.id).map(x => ({
  n: leer(x, 'N°', 'numero') || 0, fecha: leer(x, 'Fecha', 'fecha') || '', monto: leer(x, 'Monto pagado', 'numero') || 0,
  capital: leer(x, 'Capital', 'numero') || 0, interes: leer(x, 'Interés', 'numero') || 0, gastos: leer(x, 'Gastos y Seguros', 'numero') || 0,
  saldo: leer(x, 'Saldo pendiente', 'numero'), notas: leer(x, 'Notas', 'texto') || ''
})).filter(p => p.n > 0 && p.saldo != null).sort((a, b) => a.n - b.n);
if (!pagos.length) return [];
const ultimo = pagos[pagos.length - 1];
const antes = pagos.length > 1 ? pagos[pagos.length - 2] : null;
// la cuota fija del banco (capital + interés) y la tasa mensual salen de las cuotas que ya hay
const cuotaFija = Math.round(ultimo.capital + ultimo.interes);
const tasa = antes && antes.saldo > 0 && ultimo.interes > 0 ? ultimo.interes / antes.saldo : 0.013515;

// las «Cuota del carro» de Movimientos que todavía no están en «Pago del Carro»
const cusDe = s => (String(s || '').match(/CUS\s*(\d{5,})/i) || [])[1] || '';
const yaCus = new Set(pagos.map(p => cusDe(p.notas)).filter(Boolean));
const movs = $('Movimientos (cuotas)').all().map(i => i.json).filter(x => x && x.id).map(x => ({
  concepto: leer(x, 'Concepto', 'titulo') || '', tipo: leer(x, 'Tipo', 'select') || '', monto: leer(x, 'Monto', 'numero') || 0,
  fecha: leer(x, 'Fecha', 'fecha') || '', notas: leer(x, 'Notas', 'texto') || ''
})).filter(m => norm(m.concepto) === 'cuota del carro' && m.tipo === 'Gasto' && m.monto > 0 && m.fecha
  && dias(m.fecha) - dias(ultimo.fecha) >= 15            // una cuota por mes: lo de antes ya quedó registrado
  && !(cusDe(m.notas) && yaCus.has(cusDe(m.notas))))
  .sort((a, b) => a.fecha.localeCompare(b.fecha));

const salida = [];
let saldo = ultimo.saldo, n = ultimo.n, fechaAnt = ultimo.fecha;
for (const m of movs) {
  if (dias(m.fecha) - dias(fechaAnt) < 15) continue;     // dos registros del mismo mes: solo cuenta el primero
  const interes = r2(saldo * tasa);
  let gastos = m.monto - cuotaFija, capital = r2(cuotaFija - interes), nota = '';
  // si el valor no se parece a la cuota normal, todo lo que pasa del interés y los seguros de siempre se toma como capital
  if (gastos < 0 || gastos > 400000) { gastos = ultimo.gastos; capital = r2(m.monto - interes - gastos); nota = ' · valor distinto a la cuota normal: revísala'; }
  saldo = r2(saldo - capital); n += 1; fechaAnt = m.fecha;
  const cus = cusDe(m.notas);
  salida.push({ json: { titulo: 'Cuota ' + n, n, fecha: m.fecha, monto: m.monto, capital, interes, gastos, saldo,
    notas: (cus ? 'PSE · CUS ' + cus + ' · ' : '') + 'Registrada sola desde Movimientos' + nota } });
}
return salida;
